/*
 * Academic Serif
 * Visual acadêmico, com serifas e largura de leitura menor para textos extensos.
 * Tema independente para HTML gerado a partir de Markdown.
 */

:root {
  --bg: #FFFDF8;
  --surface: #F7F3EA;
